<template>
  <ConfirmationDialog
    v-model="model"
    :title="title"
    :description="description"
    :confirm-btn-text="confirmText"
    @confirm="onConfirm"
    @update:model-value="
      (value) => {
        if (!value && !isConfirmed) {
          onCancel();
        }
      }
    "
  />
</template>

<script lang="ts">
// Module scope (runs once, shared by every instance): keyed by the navigation target so
// that concurrent guards on one page resolve from a single confirmation instead of one each.
const inFlightDecision = new Map<string, Promise<boolean>>();
</script>

<script lang="ts" setup>
import type { RouteLocationNormalized } from '#vue-router';
import { isEqual } from 'lodash';

interface Props {
  title?: string;
  description?: string;
  confirmText?: string;
  savedData?: any;
  changedData?: any;
  isGuardDisabled?: boolean;
}

const props = defineProps<Props>();

interface Emits {
  (e: 'confirm'): void;
  (e: 'cancel'): void;
}

const emit = defineEmits<Emits>();

const model = ref<boolean>(false);

let resolveGuard: ((allow: boolean) => void) | null = null;
const isConfirmed = ref(false);

function onConfirm() {
  isConfirmed.value = true;
  model.value = false;
  resolveGuard?.(true);
  emit('confirm');
}

function onCancel() {
  resolveGuard?.(false);
  emit('cancel');
}

function askConfirmation(): Promise<boolean> {
  model.value = true;
  return new Promise((resolve) => {
    resolveGuard = resolve;
  });
}

async function handleRouteChange(to: RouteLocationNormalized, from: RouteLocationNormalized) {
  isConfirmed.value = false;
  console.debug('navigation guard', 'saved:', props.savedData, 'changed:', props.changedData);
  if (isEqual(props.savedData, props.changedData) || props.isGuardDisabled) {
    console.debug('No changes detected, allowing route change');
    return true;
  }
  // A page can have several dirty NavigationGuards active at once (e.g. multiple form
  // sections). Router guards run sequentially, so without this each guard would pop its
  // own dialog for the same navigation. Share one decision across all guards firing for
  // the same to/from so the user only confirms once per navigation attempt.
  const pending = inFlightDecision.get(to.fullPath);
  if (pending) {
    return await pending;
  }
  const decision = askConfirmation();
  inFlightDecision.set(to.fullPath, decision);
  try {
    return await decision;
  } finally {
    inFlightDecision.delete(to.fullPath);
  }
}

const beforeUnloadHandler = async (event: BeforeUnloadEvent): Promise<void> => {
  if (!isEqual(props.savedData, props.changedData) && !props.isGuardDisabled) {
    event.preventDefault();
    event.returnValue = '';
  }
};

useEventListener(window, 'beforeunload', beforeUnloadHandler);

onBeforeRouteUpdate(handleRouteChange);
onBeforeRouteLeave(handleRouteChange);
</script>

<style lang="scss" scoped></style>
